#include <iostream>
#include <cmath>
using namespace std;

int main() {
    long long a, b, n;
    cin >> a >> b >> n;
    long double a1 = a, b1 = b;
    long double min_diff = 1e9;
    long double base_ratio = a1 / b1;
    long long best_num, best_den;
    for (long long i = 1; i <= n; ++i) {
        long long current_num = (a * i) / b;
        long double current_ratio = current_num;
        long double diff1 = fabs(current_ratio / i - base_ratio);
        long double diff2 = fabs((current_ratio + 1.0) / i - base_ratio);
        if (diff1 < min_diff || (diff1 == min_diff && (i < best_den || (i == best_den && current_num < best_num)))) {
            min_diff = diff1;
            best_num = current_num;
            best_den = i;
        }
        if (diff2 < min_diff || (diff2 == min_diff && (i < best_den || (i == best_den && current_num + 1 < best_num)))) {
            min_diff = diff2;
            best_num = current_num + 1;
            best_den = i;
        }
        if (current_num > 0) {
            long double diff3 = fabs((current_num - 1.0) / i - base_ratio);
            if (diff3 < min_diff || (diff3 == min_diff && (i < best_den || (i == best_den && current_num - 1 < best_num)))) {
                min_diff = diff3;
                best_num = current_num - 1;
                best_den = i;
            }
        }
    }
    cout << best_num << "/" << best_den << endl;
    return 0;
}
